// Bit-exact check of HarborFrameHeaderParse (the keyframe uncompressed_header
// FSM, Increment A: prefix through quantization_params) vs the SW reference
// parseFrameHeader. A randomized writer mirrors the SW syntax to emit
// well-formed intra-keyframe headers (single superblock, superres off, no
// decoder model / film grain) plus enough zero padding that the SW parser
// completes its (deferred-here) tail without throwing. The SW parse is the
// golden, the HDL must reproduce every field through quantization_params plus
// the cursor position at that point.

// Minimal sequence-header holder (only the fields the writer/injection need),
// replacing the SW SequenceHeader now that the golden is captured.
class _Seq {
  bool reducedStillPicture = false;
  bool frameIdNumbersPresent = false;
  int seqForceScreenContentTools = 0;
  int seqForceIntegerMv = 0;
  bool enableOrderHint = false;
  int orderHintBits = 0;
  bool decoderModelInfoPresent = false;
  int frameWidthBitsMinus1 = 0;
  int frameHeightBitsMinus1 = 0;
  int maxFrameWidthMinus1 = 0;
  int maxFrameHeightMinus1 = 0;
  bool enableSuperres = false;
  bool use128x128Superblock = false;
  bool monoChrome = false;
  int numPlanes = 3;
  int subsamplingX = 1;
  int subsamplingY = 1;
  bool separateUvDeltaQ = false;
  bool enableCdef = false;
  bool enableRestoration = false;
  bool filmGrainParamsPresent = false;
}

int _tileLog2(int blkSize, int target) {
  var k = 0;
  while ((blkSize << k) < target) {
    k++;
  }
  return k;
}

