class _W {
  final bits = <int>[];
  void f(int value, int n) {
    for (var k = n - 1; k >= 0; k--) {
      bits.add((value >> k) & 1);
    }
  }

  int get len => bits.length;

  List<int> toBytes(int len) {
    final out = List.filled(len, 0);
    for (var i = 0; i < bits.length && i < len * 8; i++) {
      if (bits[i] != 0) out[i >> 3] |= 1 << (7 - (i & 7));
    }
    return out;
  }
}

// A randomly configured keyframe-friendly sequence header (built directly).
_Seq _seq(Random rng) {
  final s = _Seq();
  s.reducedStillPicture = false;
  s.frameIdNumbersPresent = false;
  s.seqForceScreenContentTools = [0, 1, 2][rng.nextInt(3)];
  s.seqForceIntegerMv = [0, 1, 2][rng.nextInt(3)];
  s.enableOrderHint = rng.nextBool();
  s.orderHintBits = s.enableOrderHint ? rng.nextInt(7) + 1 : 0;
  s.decoderModelInfoPresent = false;
  s.frameWidthBitsMinus1 = rng.nextInt(7) + 3; // 3..9 bits
  s.frameHeightBitsMinus1 = rng.nextInt(7) + 3;
  // mixed sizes: small (single SB) and large (multi-superblock => tile loops).
  s.maxFrameWidthMinus1 = rng.nextInt(1 << (s.frameWidthBitsMinus1 + 1));
  s.maxFrameHeightMinus1 = rng.nextInt(1 << (s.frameHeightBitsMinus1 + 1));
  s.enableSuperres = rng.nextBool();
  s.use128x128Superblock = false;
  s.monoChrome = false;
  s.numPlanes = 3;
  s.subsamplingX = 1;
  s.subsamplingY = 1;
  s.separateUvDeltaQ = rng.nextBool();
  s.enableCdef = rng.nextBool();
  s.enableRestoration = rng.nextBool();
  s.filmGrainParamsPresent = rng.nextBool();
  return s;
}

const _selScreen = 2;
const _selIntMv = 2;

// Returns (bytes, bitsAfterQuant) for a random in-scope keyframe header.
(List<int>, int) _build(Random rng, _Seq s) {
  final w = _W();
  bool rb() => rng.nextBool();

  w.f(0, 1); // show_existing_frame = 0
  w.f(0, 2); // frame_type = KEY_FRAME (intra)
  final showFrame = rb();
  w.f(showFrame ? 1 : 0, 1);
  var showable = false; // keyframe initial showable = (type != KEY) = false
  if (!showFrame) {
    showable = rb();
    w.f(showable ? 1 : 0, 1);
  }
  if (!showFrame)
    w.f(0, 1); // error_resilient_mode = 0 (KEY&&show would force 1)
  final disableCdf = rb();
  w.f(disableCdf ? 1 : 0, 1);
  var allowScreen = s.seqForceScreenContentTools != 0;
  if (s.seqForceScreenContentTools == _selScreen) {
    allowScreen = rb();
    w.f(allowScreen ? 1 : 0, 1);
  }
  if (allowScreen && s.seqForceIntegerMv == _selIntMv) {
    w.f(rb() ? 1 : 0, 1); // force_integer_mv
  }
  final frameSizeOverride = rb();
  w.f(frameSizeOverride ? 1 : 0, 1);
  if (s.orderHintBits > 0)
    w.f(rng.nextInt(1 << s.orderHintBits), s.orderHintBits);
  if (!showFrame) w.f(rng.nextInt(256), 8); // refresh_frame_flags (err==0)
  int frameWidth, frameHeight;
  if (frameSizeOverride) {
    final wm1 = rng.nextInt(1 << (s.frameWidthBitsMinus1 + 1));
    final hm1 = rng.nextInt(1 << (s.frameHeightBitsMinus1 + 1));
    w.f(wm1, s.frameWidthBitsMinus1 + 1);
    w.f(hm1, s.frameHeightBitsMinus1 + 1);
    frameWidth = wm1 + 1;
    frameHeight = hm1 + 1;
  } else {
    frameWidth = s.maxFrameWidthMinus1 + 1;
    frameHeight = s.maxFrameHeightMinus1 + 1;
  }
  if (s.enableSuperres) w.f(0, 1); // use_superres = 0
  final renderDiff = rb();
  w.f(renderDiff ? 1 : 0, 1);
  if (renderDiff) {
    w.f(rng.nextInt(1 << 16), 16);
    w.f(rng.nextInt(1 << 16), 16);
  }
  var allowIntrabc = false;
  if (allowScreen) {
    allowIntrabc = rb();
    w.f(allowIntrabc ? 1 : 0, 1); // allow_intrabc
  }
  if (!disableCdf) w.f(rb() ? 1 : 0, 1); // disable_frame_end_update_cdf
  // tile_info (uniform spacing), mirroring SW _tileInfo.
  final miCols = 2 * ((frameWidth + 7) >> 3);
  final miRows = 2 * ((frameHeight + 7) >> 3);
  final sbCols = (miCols + 15) >> 4; // use128 = false
  final sbRows = (miRows + 15) >> 4;
  const maxTileWidthSb = 4096 >> 6; // 64
  const maxTileAreaSb = (4096 * 2304) >> 12; // 2304
  final minLog2TileCols = _tileLog2(maxTileWidthSb, sbCols);
  final maxLog2TileCols = _tileLog2(1, sbCols < 64 ? sbCols : 64);
  final maxLog2TileRows = _tileLog2(1, sbRows < 64 ? sbRows : 64);
  final minLog2Tiles = max(
    minLog2TileCols,
    _tileLog2(maxTileAreaSb, sbRows * sbCols),
  );
  w.f(1, 1); // uniform_tile_spacing_flag = 1
  var tileColsLog2 = minLog2TileCols;
  while (tileColsLog2 < maxLog2TileCols) {
    final inc = rb();
    w.f(inc ? 1 : 0, 1);
    if (inc) {
      tileColsLog2++;
    } else {
      break;
    }
  }
  final minLog2TileRows = max(minLog2Tiles - tileColsLog2, 0);
  var tileRowsLog2 = minLog2TileRows;
  while (tileRowsLog2 < maxLog2TileRows) {
    final inc = rb();
    w.f(inc ? 1 : 0, 1);
    if (inc) {
      tileRowsLog2++;
    } else {
      break;
    }
  }
  if (tileColsLog2 > 0 || tileRowsLog2 > 0) {
    w.f(
      rng.nextInt(1 << (tileColsLog2 + tileRowsLog2)),
      tileColsLog2 + tileRowsLog2,
    ); // context_update_tile_id
    w.f(rng.nextInt(4), 2); // tile_size_bytes_minus_1
  }
  // quantization_params. ~1/8 of frames are coded-lossless (base_q==0, no
  // deltas) to exercise the loop-filter lossless skip.
  final lossless = rng.nextInt(8) == 0;
  w.f(lossless ? 0 : (rng.nextInt(255) + 1), 8); // base_q_idx
  void deltaQ() {
    if (!lossless && rb()) {
      w.f(1, 1);
      w.f(rng.nextInt(128), 7); // su(7): -64..63
    } else {
      w.f(0, 1);
    }
  }

  deltaQ(); // delta_q_y_dc
  if (s.numPlanes > 1) {
    var diffUv = false;
    if (s.separateUvDeltaQ) {
      diffUv = rb();
      w.f(diffUv ? 1 : 0, 1);
    }
    deltaQ(); // u_dc
    deltaQ(); // u_ac
    if (diffUv) {
      deltaQ(); // v_dc
      deltaQ(); // v_ac
    }
  }
  final usingQm = rb();
  w.f(usingQm ? 1 : 0, 1);
  if (usingQm) {
    w.f(rng.nextInt(16), 4); // qm_y
    w.f(rng.nextInt(16), 4); // qm_u
    if (s.separateUvDeltaQ) w.f(rng.nextInt(16), 4); // qm_v
  }

  w.f(0, 1); // segmentation_enabled = 0
  // base_q is 0 only in the lossless case (no deltaQ either).
  final baseQPos = !lossless;
  var deltaQPresent = false;
  if (baseQPos) {
    deltaQPresent = rb();
    w.f(deltaQPresent ? 1 : 0, 1); // delta_q_present
    if (deltaQPresent) w.f(rng.nextInt(4), 2); // delta_q_res
  }
  if (deltaQPresent && !allowIntrabc) {
    final deltaLfPresent = rb();
    w.f(deltaLfPresent ? 1 : 0, 1);
    if (deltaLfPresent) {
      w.f(rng.nextInt(4), 2); // delta_lf_res
      w.f(rb() ? 1 : 0, 1); // delta_lf_multi
    }
  }
  // loop_filter_params: skipped when coded-lossless or allow_intrabc.
  if (!lossless && !allowIntrabc) {
    final lvl0 = rng.nextInt(64);
    final lvl1 = rng.nextInt(64);
    w.f(lvl0, 6);
    w.f(lvl1, 6);
    if (s.numPlanes > 1 && (lvl0 != 0 || lvl1 != 0)) {
      w.f(rng.nextInt(64), 6); // level[2]
      w.f(rng.nextInt(64), 6); // level[3]
    }
    w.f(rng.nextInt(8), 3); // sharpness
    final deltaEnabled = rb();
    w.f(deltaEnabled ? 1 : 0, 1);
    if (deltaEnabled) {
      final update = rb();
      w.f(update ? 1 : 0, 1);
      if (update) {
        for (var i = 0; i < 8; i++) {
          if (rb()) {
            w.f(1, 1);
            w.f(rng.nextInt(128), 7); // su(7)
          } else {
            w.f(0, 1);
          }
        }
        for (var i = 0; i < 2; i++) {
          if (rb()) {
            w.f(1, 1);
            w.f(rng.nextInt(128), 7);
          } else {
            w.f(0, 1);
          }
        }
      }
    }
  }
  // cdef_params: skipped when coded-lossless, allow_intrabc, or !enable_cdef.
  if (!lossless && !allowIntrabc && s.enableCdef) {
    w.f(rng.nextInt(4), 2); // cdef_damping_minus_3
    final cdefBits = rng.nextInt(4);
    w.f(cdefBits, 2);
    final nC = 1 << cdefBits;
    for (var i = 0; i < nC; i++) {
      w.f(rng.nextInt(16), 4); // y_pri
      w.f(rng.nextInt(4), 2); // y_sec (raw; 3->4 on read)
      if (s.numPlanes > 1) {
        w.f(rng.nextInt(16), 4); // uv_pri
        w.f(rng.nextInt(4), 2); // uv_sec
      }
    }
  }
  // lr_params: skipped when all-lossless, allow_intrabc, or !enable_restoration.
  final allLossless = lossless; // superres off => upscaledWidth == frameWidth
  if (!allLossless && !allowIntrabc && s.enableRestoration) {
    var usesLr = false, usesChromaLr = false;
    for (var i = 0; i < s.numPlanes; i++) {
      final lrType = rng.nextInt(4);
      w.f(lrType, 2);
      if (lrType != 0) {
        usesLr = true;
        if (i > 0) usesChromaLr = true;
      }
    }
    if (usesLr) {
      // use128 is false here.
      final b1 = rng.nextInt(2);
      w.f(b1, 1);
      if (b1 != 0) w.f(rng.nextInt(2), 1); // second unit-shift bit
      if (s.subsamplingX != 0 && s.subsamplingY != 0 && usesChromaLr) {
        w.f(rng.nextInt(2), 1); // lr_uv_shift
      }
    }
  }
  // read_tx_mode
  if (!lossless) w.f(rb() ? 1 : 0, 1); // tx_mode_select
  // frame_reference_mode / skip_mode / allow_warped read nothing (intra).
  w.f(rb() ? 1 : 0, 1); // reduced_tx_set
  // film_grain_params: apply_grain = 0 (applied grain deferred).
  if (s.filmGrainParamsPresent && (showFrame || showable)) {
    w.f(0, 1); // apply_grain = 0
  }
  final afterHeader = w.len;
  return (w.toBytes(64), afterHeader);
}

void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  const maxBytes = 64;

  test(
    'HarborFrameHeaderParse: bit-exact vs SW parseFrameHeader (keyframe)',
    () async {
      final p = HarborFrameHeaderParse(maxBytes: maxBytes);
      final clk = SimpleClockGenerator(10).clk;
      final reset = Logic(name: 'reset');
      final start = Logic(name: 'start');
      final bytes = Logic(name: 'bytes', width: maxBytes * 8);

      // seq inputs
      final iReduced = Logic(name: 'i_reduced');
      final iFrameId = Logic(name: 'i_frame_id');
      final iDeltaIdM2 = Logic(name: 'i_delta_id', width: 4);
      final iAddIdM1 = Logic(name: 'i_add_id', width: 3);
      final iForceScreen = Logic(name: 'i_force_screen', width: 2);
      final iForceIntMv = Logic(name: 'i_force_int_mv', width: 2);
      final iOrderHintBits = Logic(name: 'i_order_hint_bits', width: 4);
      final iEnableOrderHint = Logic(name: 'i_enable_order_hint');
      final iDecModel = Logic(name: 'i_dec_model');
      final iWBitsM1 = Logic(name: 'i_w_bits', width: 4);
      final iHBitsM1 = Logic(name: 'i_h_bits', width: 4);
      final iMaxWM1 = Logic(name: 'i_max_w', width: 32);
      final iMaxHM1 = Logic(name: 'i_max_h', width: 32);
      final iEnableSuperres = Logic(name: 'i_enable_superres');
      final iUse128 = Logic(name: 'i_use128');
      final iNumPlanes = Logic(name: 'i_num_planes', width: 2);
      final iSepUv = Logic(name: 'i_sep_uv');
      final iEnableCdef = Logic(name: 'i_enable_cdef');
      final iEnableRestoration = Logic(name: 'i_enable_restoration');
      final iSubX = Logic(name: 'i_sub_x');
      final iSubY = Logic(name: 'i_sub_y');
      final iFilmGrain = Logic(name: 'i_film_grain');

      p.input('clk').srcConnection! <= clk;
      p.input('reset').srcConnection! <= reset;
      p.input('start').srcConnection! <= start;
      p.input('bytes').srcConnection! <= bytes;
      p.input('seq_reduced_still_picture').srcConnection! <= iReduced;
      p.input('seq_frame_id_numbers_present').srcConnection! <= iFrameId;
      p.input('seq_delta_frame_id_length_minus2').srcConnection! <= iDeltaIdM2;
      p.input('seq_additional_frame_id_length_minus1').srcConnection! <=
          iAddIdM1;
      p.input('seq_force_screen_content_tools').srcConnection! <= iForceScreen;
      p.input('seq_force_integer_mv').srcConnection! <= iForceIntMv;
      p.input('seq_order_hint_bits').srcConnection! <= iOrderHintBits;
      p.input('seq_enable_order_hint').srcConnection! <= iEnableOrderHint;
      p.input('seq_decoder_model_info_present').srcConnection! <= iDecModel;
      p.input('seq_frame_width_bits_minus1').srcConnection! <= iWBitsM1;
      p.input('seq_frame_height_bits_minus1').srcConnection! <= iHBitsM1;
      p.input('seq_max_frame_width_minus1').srcConnection! <= iMaxWM1;
      p.input('seq_max_frame_height_minus1').srcConnection! <= iMaxHM1;
      p.input('seq_enable_superres').srcConnection! <= iEnableSuperres;
      p.input('seq_use_128x128_superblock').srcConnection! <= iUse128;
      p.input('seq_num_planes').srcConnection! <= iNumPlanes;
      p.input('seq_separate_uv_delta_q').srcConnection! <= iSepUv;
      p.input('seq_enable_cdef').srcConnection! <= iEnableCdef;
      p.input('seq_enable_restoration').srcConnection! <= iEnableRestoration;
      p.input('seq_subsampling_x').srcConnection! <= iSubX;
      p.input('seq_subsampling_y').srcConnection! <= iSubY;
      p.input('seq_film_grain_params_present').srcConnection! <= iFilmGrain;
      p.input('shown_frame_type').srcConnection! <= Const(0, width: 2);
      p.input('shown_order_hint').srcConnection! <= Const(0, width: 8);

      await p.build();

      reset.inject(1);
      start.inject(0);
      bytes.inject(0);
      for (final l in [
        iReduced,
        iFrameId,
        iEnableOrderHint,
        iDecModel,
        iEnableSuperres,
        iUse128,
        iSepUv,
        iEnableCdef,
        iEnableRestoration,
        iSubX,
        iSubY,
        iFilmGrain,
      ]) {
        l.inject(0);
      }
      iDeltaIdM2.inject(0);
      iAddIdM1.inject(0);
      iForceScreen.inject(0);
      iForceIntMv.inject(0);
      iOrderHintBits.inject(0);
      iWBitsM1.inject(3);
      iHBitsM1.inject(3);
      iMaxWM1.inject(0);
      iMaxHM1.inject(0);
      iNumPlanes.inject(3);
      Simulator.setMaxSimTime(200000000);
      unawaited(Simulator.run());
      await clk.nextPosedge;

      BigInt pack(List<int> b) {
        var v = BigInt.zero;
        for (var i = 0; i < b.length; i++) {
          v |= BigInt.from(b[i] & 0xFF) << (i * 8);
        }
        return v;
      }

      int o(String name) => p.output(name).value.toInt();
      int sgn8(String name) {
        final v = o(name);
        return v >= 128 ? v - 256 : v;
      }

      final rng = Random(0xC0FFEE);
      var sawOverride = false, sawRender = false, sawIntrabc = false;
      var sawQm = false, sawNoShow = false, sawDelta = false;
      var sawLossless = false, sawLfUpdate = false, sawDeltaQ = false;
      var sawCdef = false, sawUsesLr = false, sawTxSelect = false;
      var sawMultiTile = false;
      for (var iter = 0; iter < 400; iter++) {
        final s = _seq(rng);
        final (buf, afterHeader) = _build(rng, s);
        final exp = _golden[iter];

        if (exp.frameWidth != s.maxFrameWidthMinus1 + 1) sawOverride = true;
        if (exp.renderWidth != exp.upscaledWidth) sawRender = true;
        if (exp.allowIntrabc) sawIntrabc = true;
        if (exp.usingQmatrix) sawQm = true;
        if (!exp.showFrame) sawNoShow = true;
        if (exp.deltaQYDc != 0 || exp.deltaQUDc != 0) sawDelta = true;
        if (exp.codedLossless) sawLossless = true;
        if (exp.deltaQPresent) sawDeltaQ = true;
        if (exp.loopFilterDeltaEnabled &&
            exp.loopFilterRefDeltas.toString() !=
                [1, 0, 0, 0, -1, 0, -1, -1].toString()) {
          sawLfUpdate = true;
        }
        if (exp.cdefBits > 0) sawCdef = true;
        if (exp.usesLr) sawUsesLr = true;
        if (exp.txMode == 2) sawTxSelect = true;
        if (exp.tileColsLog2 > 0 || exp.tileRowsLog2 > 0) sawMultiTile = true;

        // drive seq inputs
        iReduced.inject(0);
        iFrameId.inject(0);
        iDeltaIdM2.inject(0);
        iAddIdM1.inject(0);
        iForceScreen.inject(s.seqForceScreenContentTools);
        iForceIntMv.inject(s.seqForceIntegerMv);
        iOrderHintBits.inject(s.orderHintBits);
        iEnableOrderHint.inject(s.enableOrderHint ? 1 : 0);
        iDecModel.inject(0);
        iWBitsM1.inject(s.frameWidthBitsMinus1);
        iHBitsM1.inject(s.frameHeightBitsMinus1);
        iMaxWM1.inject(s.maxFrameWidthMinus1);
        iMaxHM1.inject(s.maxFrameHeightMinus1);
        iEnableSuperres.inject(s.enableSuperres ? 1 : 0);
        iUse128.inject(0);
        iNumPlanes.inject(s.numPlanes);
        iSepUv.inject(s.separateUvDeltaQ ? 1 : 0);
        iEnableCdef.inject(s.enableCdef ? 1 : 0);
        iEnableRestoration.inject(s.enableRestoration ? 1 : 0);
        iSubX.inject(s.subsamplingX);
        iSubY.inject(s.subsamplingY);
        iFilmGrain.inject(s.filmGrainParamsPresent ? 1 : 0);

        reset.inject(1);
        await clk.nextPosedge;
        reset.inject(0);
        bytes.inject(pack(buf));
        start.inject(1);
        await clk.nextPosedge;
        start.inject(0);
        var guard = 0;
        while (p.output('done').value.toInt() != 1) {
          await clk.nextPosedge;
          if (++guard > 2000) fail('timeout iter=$iter');
        }
        expect(o('unsupported'), equals(0), reason: 'iter=$iter unsupported');

        void chk(String name, int want, String label) =>
            expect(o(name), equals(want), reason: 'iter=$iter $label');
        void chkB(String name, bool want, String label) =>
            expect(o(name), equals(want ? 1 : 0), reason: 'iter=$iter $label');

        chk('frame_type', exp.frameType, 'frame_type');
        chkB('frame_is_intra', exp.frameIsIntra, 'frame_is_intra');
        chkB('show_frame', exp.showFrame, 'show_frame');
        chkB('showable_frame', exp.showableFrame, 'showable');
        chkB('error_resilient_mode', exp.errorResilientMode, 'err');
        chkB('disable_cdf_update', exp.disableCdfUpdate, 'disable_cdf');
        chkB(
          'allow_screen_content_tools',
          exp.allowScreenContentTools,
          'screen',
        );
        chk('force_integer_mv', exp.forceIntegerMv, 'force_mv');
        chkB('allow_intrabc', exp.allowIntrabc, 'intrabc');
        chk('order_hint', exp.orderHint, 'order_hint');
        chk('refresh_frame_flags', exp.refreshFrameFlags, 'refresh');
        chk('frame_width', exp.frameWidth, 'frame_width');
        chk('frame_height', exp.frameHeight, 'frame_height');
        chk('upscaled_width', exp.upscaledWidth, 'upscaled');
        chk('render_width', exp.renderWidth, 'render_w');
        chk('render_height', exp.renderHeight, 'render_h');
        chk('superres_denom', exp.superresDenom, 'superres_denom');
        chkB(
          'disable_frame_end_update_cdf',
          exp.disableFrameEndUpdateCdf,
          'fe_cdf',
        );
        chk('tile_cols', exp.tileCols, 'tile_cols');
        chk('tile_rows', exp.tileRows, 'tile_rows');
        chk('tile_cols_log2', exp.tileColsLog2, 'tile_cols_log2');
        chk('tile_rows_log2', exp.tileRowsLog2, 'tile_rows_log2');
        chk('context_update_tile_id', exp.contextUpdateTileId, 'ctx_tile');
        chk('tile_size_bytes', exp.tileSizeBytes, 'tile_size_bytes');
        chk('base_q_idx', exp.baseQIdx, 'base_q');
        expect(
          sgn8('delta_q_y_dc'),
          equals(exp.deltaQYDc),
          reason: 'iter=$iter dq_ydc',
        );
        expect(
          sgn8('delta_q_u_dc'),
          equals(exp.deltaQUDc),
          reason: 'iter=$iter dq_udc',
        );
        expect(
          sgn8('delta_q_u_ac'),
          equals(exp.deltaQUAc),
          reason: 'iter=$iter dq_uac',
        );
        expect(
          sgn8('delta_q_v_dc'),
          equals(exp.deltaQVDc),
          reason: 'iter=$iter dq_vdc',
        );
        expect(
          sgn8('delta_q_v_ac'),
          equals(exp.deltaQVAc),
          reason: 'iter=$iter dq_vac',
        );
        chkB('using_qmatrix', exp.usingQmatrix, 'using_qm');
        chk('qm_y', exp.qmY, 'qm_y');
        chk('qm_u', exp.qmU, 'qm_u');
        chk('qm_v', exp.qmV, 'qm_v');
        // tail fields
        chkB('segmentation_enabled', exp.segmentationEnabled, 'seg_enabled');
        chkB('delta_q_present', exp.deltaQPresent, 'delta_q_present');
        chk('delta_q_res', exp.deltaQRes, 'delta_q_res');
        chkB('delta_lf_present', exp.deltaLfPresent, 'delta_lf_present');
        chk('delta_lf_res', exp.deltaLfRes, 'delta_lf_res');
        chkB('delta_lf_multi', exp.deltaLfMulti, 'delta_lf_multi');
        chkB('coded_lossless', exp.codedLossless, 'coded_lossless');
        chk('loop_filter_level_0', exp.loopFilterLevel[0], 'lf_level0');
        chk('loop_filter_level_1', exp.loopFilterLevel[1], 'lf_level1');
        chk('loop_filter_level_2', exp.loopFilterLevel[2], 'lf_level2');
        chk('loop_filter_level_3', exp.loopFilterLevel[3], 'lf_level3');
        chk('loop_filter_sharpness', exp.loopFilterSharpness, 'lf_sharp');
        chkB(
          'loop_filter_delta_enabled',
          exp.loopFilterDeltaEnabled,
          'lf_delta_en',
        );
        final refPacked = p.output('loop_filter_ref_deltas').value.toBigInt();
        for (var i = 0; i < 8; i++) {
          final byte = ((refPacked >> (i * 8)) & BigInt.from(0xff)).toInt();
          final signed = byte >= 128 ? byte - 256 : byte;
          expect(
            signed,
            equals(exp.loopFilterRefDeltas[i]),
            reason: 'iter=$iter lf_ref_delta[$i]',
          );
        }
        final modePacked = p.output('loop_filter_mode_deltas').value.toBigInt();
        for (var i = 0; i < 2; i++) {
          final byte = ((modePacked >> (i * 8)) & BigInt.from(0xff)).toInt();
          final signed = byte >= 128 ? byte - 256 : byte;
          expect(
            signed,
            equals(exp.loopFilterModeDeltas[i]),
            reason: 'iter=$iter lf_mode_delta[$i]',
          );
        }
        // cdef
        chk('cdef_damping_minus3', exp.cdefDampingMinus3, 'cdef_damping');
        chk('cdef_bits', exp.cdefBits, 'cdef_bits');
        final nC = 1 << exp.cdefBits;
        int nib(String name, int i) =>
            ((p.output(name).value.toBigInt() >> (i * 4)) & BigInt.from(0xf))
                .toInt();
        for (var i = 0; i < nC; i++) {
          expect(
            nib('cdef_y_pri_strength', i),
            equals(exp.cdefYPriStrength[i]),
            reason: 'iter=$iter cdef_y_pri[$i]',
          );
          expect(
            nib('cdef_y_sec_strength', i),
            equals(exp.cdefYSecStrength[i]),
            reason: 'iter=$iter cdef_y_sec[$i]',
          );
          expect(
            nib('cdef_uv_pri_strength', i),
            equals(exp.cdefUvPriStrength[i]),
            reason: 'iter=$iter cdef_uv_pri[$i]',
          );
          expect(
            nib('cdef_uv_sec_strength', i),
            equals(exp.cdefUvSecStrength[i]),
            reason: 'iter=$iter cdef_uv_sec[$i]',
          );
        }
        // lr
        final frtPacked = o('frame_restoration_type');
        for (var i = 0; i < 3; i++) {
          expect(
            (frtPacked >> (i * 2)) & 0x3,
            equals(exp.frameRestorationType[i]),
            reason: 'iter=$iter frame_rest_type[$i]',
          );
        }
        chkB('uses_lr', exp.usesLr, 'uses_lr');
        chk('lr_size_0', exp.loopRestorationSize[0], 'lr_size_0');
        chk('lr_size_1', exp.loopRestorationSize[1], 'lr_size_1');
        chk('lr_size_2', exp.loopRestorationSize[2], 'lr_size_2');
        // tx / film grain
        chk('tx_mode', exp.txMode, 'tx_mode');
        chkB('reduced_tx_set', exp.reducedTxSet, 'reduced_tx_set');
        expect(o('apply_grain'), equals(0), reason: 'iter=$iter apply_grain');
        expect(
          o('bits_consumed'),
          equals(afterHeader),
          reason: 'iter=$iter consumed',
        );
      }
      expect(sawOverride, isTrue, reason: 'no frame_size_override seen');
      expect(sawRender, isTrue, reason: 'no render diff seen');
      expect(sawIntrabc, isTrue, reason: 'no allow_intrabc seen');
      expect(sawQm, isTrue, reason: 'no qmatrix seen');
      expect(sawNoShow, isTrue, reason: 'no show_frame==0 seen');
      expect(sawDelta, isTrue, reason: 'no nonzero deltaQ seen');
      expect(sawLossless, isTrue, reason: 'no coded-lossless frame seen');
      expect(sawLfUpdate, isTrue, reason: 'no loop-filter delta update seen');
      expect(sawDeltaQ, isTrue, reason: 'no delta_q_present seen');
      expect(sawCdef, isTrue, reason: 'no multi-strength cdef seen');
      expect(sawUsesLr, isTrue, reason: 'no loop restoration seen');
      expect(sawTxSelect, isTrue, reason: 'no TX_MODE_SELECT seen');
      expect(sawMultiTile, isTrue, reason: 'no multi-tile frame seen');
      await Simulator.endSimulation();
    },
  );
}
